#!/bin/bash
# Apply the reviewed visual update to the existing EmprendeClaro frontend only.
set -euo pipefail
app_name=''
while getopts ':i:n:s:' opt; do
 case "$opt" in i) : ;; n|s) app_name="$OPTARG" ;; *) exit 64 ;; esac
done
[[ "$(id -un)" == 'emprendeclaro' ]] || exit 77
[[ -z "$app_name" || "$app_name" == 'emprendeclaro_demo_v2' ]] || exit 64
[[ "$(pwd -P)" == '/home/emprendeclaro/apps/emprendeclaro_demo_v2' ]] || exit 77
[[ -f index.html && ! -L index.html && -O index.html ]] || exit 73
current_hash=$(sha256sum index.html | cut -d ' ' -f 1)
if [[ "$current_hash" == 'c1126e9ff9ff65e6dc0c915448202496e9424f8014f8a7959b3e4b8cc2a476f2' ]]; then
 printf '%s\n' 'La revision de diseno 2.1 ya esta instalada.'
 exit 0
fi
[[ "$current_hash" == 'eefc707fa055adad3d35e80c6b654fef556edc69b057762fac4c78ed661d7173' ]] || { printf '%s\n' 'La version publicada cambio. No se aplicaron cambios; revisa antes de actualizar.'; exit 74; }
tmp_file=$(mktemp './.diseno-21.XXXXXXXX')
trap 'rm -f -- "$tmp_file"' EXIT
base64 --decode <<'EMPRENDECLARO_PAYLOAD' | gzip --decompress > "$tmp_file"
